export type StoryPlaylist = {
  /** Encabezado del módulo (sin el ornamento, que lo pone el componente). */
  heading: string;
  /** Línea descriptiva bajo el encabezado. */
  note: string;
  /** Texto del botón que llena la cola del reproductor. */
  buttonLabel: string;
  /** IDs de temas de `musicTracks`, en el orden de reproducción deseado. */
  trackIds: string[];
};

/**
 * Personaje con mayor peso protagónico del relato (Canon de Separadores Lyzánthycos v1.0).
 * Define la paleta de separadores y acentos decorativos; "ensemble" = cian neutral #67d9ff.
 */
export type DominantCharacter = "rubi" | "yuki" | "lyzi" | "noctalypse" | "ensemble";

export type Story = {
  slug: string;
  title: string;
  teaser: string;
  characters: string[];
  accent: string;
  wordCount: number;
  readingMinutes: number;
  paragraphs: string[];
  /** Banda sonora opcional: si existe, aparece un módulo de playlist antes del relato. */
  playlist?: StoryPlaylist;
  /** Si falta o es inválido, el renderer aplica el estándar neutral ("ensemble"). */
  dominantCharacter?: DominantCharacter;
};

