      "El aire frío le tocó la piel en un lugar que prefería no exponer ante nadie.",
      "Rubí se quedó inmóvil, doblada sobre sí misma, con la bota apenas a medio salir. Sintió un calor repentino subirle a la cara —vergüenza, no fuego— y la mandíbula se le endureció tanto que le dolieron las sienes.",
      "—No digan nada —advirtió, todavía agachada.",
      "Como si el universo hubiera recibido la frase como desafío personal, un zumbido fino le pasó junto a la oreja: un zancudo, decidido a picarle justo en el cuello, donde la piel era más sensible. Rubí reaccionó con un manotazo furioso y, en el movimiento, enganchó otra vez el borde ya roto de la capa. La tela lloró un segundo desgarrón, más largo, más humillante. Al mismo tiempo, el pie herido intentó sostener un equilibrio que ya no estaba. La bota se trabó a medio camino. El banco chirrió cuando lo pateó sin querer, y Rubí se fue al suelo.",
      "El golpe resonó en toda la sala.",
